// Mock the task log phases discovery endpoint
async function mockTaskLogPhases(
  page: Page,
  taskId: string,
  phases: string[]    // e.g., ['planning', 'implementation'] or ['planning']
): Promise<void> {
  await page.route(`**/api/tasks/${taskId}/logs`, async (route) => {
    // Only handle GET requests (not sub-paths like /logs/planning)
    if (route.request().url().endsWith('/logs') || route.request().url().includes('/logs?')) {
      await route.fulfill({
        status: 200,
        contentType: "application/json",
        body: JSON.stringify({
          success: true,
          data: { phases },
        }),
      });
    } else {
      await route.continue();
    }
  });
}

// Mock task log SSE stream (similar to mockLogStreamSSE from log-streaming.spec.ts)
async function mockTaskLogStreamSSE(
  page: Page,
  taskId: string,
  phase: string,        // 'planning' or 'implementation'
  events: Array<{ line: string; timestamp?: string }>
): Promise<void> {
  const pattern = `**/api/tasks/${taskId}/logs/${phase}/stream**`;
  await page.route(pattern, async (route) => {
    let body = "";
    events.forEach((event, index) => {
      const data = JSON.stringify({
        line: event.line,
        timestamp: event.timestamp || new Date().toISOString(),
      });
      body += `event: log-line\ndata: ${data}\nid: ${index + 1}\n\n`;
    });
    await route.fulfill({
      status: 200,
      contentType: "text/event-stream",
      headers: { "Cache-Control": "no-cache", Connection: "keep-alive" },
      body,
    });
  });
}
